valid_locs = {:t, :b, :l, :r, :tl, :tr, :bl, :br}
if valid_locs.includes?(loc)
else
  raise(ArgumentError.new("unknown location #{loc}"))
end
if (loc == (:l)) || (loc == (:r))
  (1..nrows).each do |row|
    if loc == (:l)
      if !@labels_left[row]? || @labels_left[row].empty?
        @labels_left[row] = value
        @colors_left[row] = color
        break
      end
    elsif !@labels_right[row]? || @labels_right[row].empty?
      @labels_right[row] = value
      @colors_right[row] = color
      break
    end
  end
else
  @decorations[loc] = value
  @colors_deco[loc] = color
end
self

case loc
when :l
  @labels_left[row] = value
  @colors_left[row] = color
when :r
  @labels_right[row] = value
